	'invoice_round_trip' => 'Invoice number round trip',
	'invoice_round_trip_help' => 'Every order we send carries our own invoice number. If an answer is ever lost, the order is found again by looking for that number in the provider\'s order list. A verified field map only shows that the list has such a field (most older orders have it empty); it does not show that the number we send comes back. Until the master administrator records, with evidence, that it does, no real order is sent to Torod Point. Rehearsals (dry run) are not affected.',
